create role anon;create role authenticated;create schema auth;create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;create table auth.users(id uuid,email text,email_confirmed_at timestamptz);create table platform_admins(user_id uuid);create table tenants(id uuid primary key default gen_random_uuid(),shop_type text,name text,owner_name text,phone text,status text default 'active',sub_start date,sub_end date,created_at timestamptz default now(),updated_at timestamptz default now());create table shop_users(id text,auth_id uuid,tenant_id uuid,name text,owner boolean,active boolean,perms jsonb);create table shop_info(tenant_id uuid,id int,shop_name text,owner_name text,phone text);create function is_platform_admin() returns boolean language sql stable security definer as $$select exists(select 1 from platform_admins where user_id=auth.uid())$$;grant usage on schema public,auth to authenticated,anon;grant execute on function auth.uid(),is_platform_admin() to authenticated;insert into platform_admins values('00000000-0000-0000-0000-000000000001');insert into tenants(id,name,sub_end) values('00000000-0000-0000-0000-000000000010','mobile','2028-01-31');
create function admin_extend_subscription(uuid,integer) returns void language sql as $$select$$;create function admin_set_tenant_status(uuid,text) returns void language sql as $$select$$;create function admin_finish_shop(uuid,text,text,text,text,integer,text) returns void language sql as $$select$$;